package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen1Test {

    @Test
    public void testTranslate_MatchLongest() throws IOException {
        // Setup: longest=3, shortest=1
        // Map: "abc" -> "123", "ab" -> "45", "a" -> "6"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"abc", "ab", "a"},
                new CharSequence[]{"123", "45", "6"}
        );

        StringWriter out = new StringWriter();
        String input = "abcde";

        // Test greedy matching (should pick "abc")
        int result = translator.translate(input, 0, out);

        assertEquals(3, result);
        assertEquals("123", out.toString());
    }










}

