package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen1Test {









    @Test
    public void testTranslate_Branch_IndexPlusLongestExceedsLength() throws IOException {
        // This tests the branch: if (index + longest > input.length())
        // longest = 3, input.length() = 4, index = 2. 2 + 3 > 4 is true.
        // max becomes 4 / 2 = 2.
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"bc", "c"},
                new CharSequence[]{"BC", "C"}
        );

        StringWriter out = new StringWriter();
        String input = "abcd";

        // index = 2, input.subSequence(2, 2+2) is "cd". 
        // But the logic says max = input.length() / index -> 4 / 2 = 2.
        // The loop will check i=2 (subSeq "cd") and i=1 (subSeq "c").

        int result = translator.translate(input, 2, out);

        // "c" is in the map.
        assertEquals(1, result);
        assertEquals("C", out.toString());
    }


}

