public class LookupTranslator_translate_TriageGen1Test {











    @Test
    public void testTranslate_PartialMatch_MaxConstraint() throws IOException {
        // Testing the logic where max is recalculated
        // input = "abc", index = 2, longest = 3.
        // index + longest (5) > input.length (3).
        // max = 3 / 2 = 1.
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"c"},
                new CharSequence[]{"C"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        int result = translator.translate(input, 2, out);

        assertEquals(1, result);
        assertEquals("C", out.toString());
    }
}
